import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

/**
 * Реализация ограничителя частоты запросов (rate limiter) по алгоритму "Token Bucket" (ведро с токенами).
 *
 * <p>Алгоритм работает следующим образом:
 * <ul>
 *   <li>В "ведре" хранится определённое количество токенов (разрешений).</li>
 *   <li>Токены пополняются с фиксированной скоростью (например, 10 токенов в секунду).</li>
 *   <li>Каждый запрос потребляет один или несколько токенов.</li>
 *   <li>Если в ведре достаточно токенов — запрос разрешается, и токены вычитаются.</li>
 *   <li>Если токенов недостаточно — запрос отклоняется.</li>
 *   <li>Максимальное количество токенов в ведре ограничено (burst capacity).</li>
 * </ul>
 *
 * <p>Класс потокобезопасен и может использоваться в многопоточной среде.
 */
public class TokenBucketRateLimiter {

    /**
     * Максимальное количество токенов, которое может храниться в ведре.
     * Определяет максимальный burst (всплеск) запросов, которые можно обработать мгновенно.
     */
    private final long maxTokens;

    /**
     * Скорость пополнения ведра: количество токенов, добавляемых в секунду.
     */
    private final double refillRatePerSecond;

    /**
     * Текущее количество токенов в ведре.
     * Хранится как double для точности при дробных пополнениях.
     */
    private double currentTokens;

    /**
     * Время последнего обновления ведра в наносекундах (System.nanoTime()).
     * Используется для расчёта количества токенов, которые нужно добавить с момента последнего обновления.
     */
    private long lastRefillTimestamp;

    /**
     * Замок для обеспечения потокобезопасности при обновлении состояния ведра.
     */
    private final ReentrantLock lock;

    /**
     * Создаёт новый ограничитель частоты запросов по алгоритму Token Bucket.
     *
     * @param maxTokens          максимальное количество токенов в ведре (burst capacity)
     * @param refillRatePerSecond скорость пополнения ведра (токенов в секунду)
     * @throws IllegalArgumentException если maxTokens <= 0 или refillRatePerSecond <= 0
     */
    public TokenBucketRateLimiter(long maxTokens, double refillRatePerSecond) {
        if (maxTokens <= 0) {
            throw new IllegalArgumentException("maxTokens должен быть больше 0");
        }
        if (refillRatePerSecond <= 0) {
            throw new IllegalArgumentException("refillRatePerSecond должен быть больше 0");
        }
        this.maxTokens = maxTokens;
