/// Итератор по строкам большого текстового файла без загрузки всего файла в память.
///
/// Этот итератор читает файл построчно, используя буферизированное чтение.
/// Каждая строка возвращается как `String`, включая завершающий символ новой строки
/// (если он присутствует). Для строк без завершающего `\n` (например, последняя
/// строка файла) символ новой строки не добавляется.
///
/// # Пример
///
/// ```no_run
/// use std::path::Path;
///
/// let path = Path::new("large_file.txt");
/// let mut iter = LineIterator::new(path).expect("Не удалось открыть файл");
/// for line in iter {
///     let line = line.expect("Ошибка чтения строки");
///     println!("{}", line);
/// }
/// ```
pub struct LineIterator {
    reader: BufReader<File>,
    buffer: Vec<u8>,
    /// Флаг, указывающий, что буфер уже был заполнен хотя бы один раз.
    /// Используется для корректной обработки конца файла.
    eof_reached: bool,
    /// Флаг, указывающий, что итератор уже исчерпан.
    exhausted: bool,
}

impl LineIterator {
    /// Создаёт новый итератор по строкам для файла по указанному пути.
    ///
    /// Открывает файл и подготавливает буферизированный читатель.
    ///
    /// # Аргументы
    ///
    /// * `path` — путь к файлу, который будет читаться построчно.
    ///
    /// # Возвращает
    ///
    /// * `Ok(LineIterator)` — успешно созданный итератор.
    /// * `Err(io::Error)` — ошибка при открытии файла.
    ///
    /// # Пример
    ///
    /// ```no_run
    /// use std::path::Path;
    ///
    /// let iter = LineIterator::new(Path::new("example.txt")).expect("Не удалось открыть файл");
    /// ```
    pub fn new<P: AsRef<Path>>(path: P) -> io::Result<LineIterator> {
        let file = File::open(path)?;
        // Используем BufReader с размером буфера 8 КБ для эффективного чтения.
        // BufReader минимизирует количество системных вызовов read().
