public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл повторных попыток выполнения действия.
    // Переменная i отслеживает текущий номер попытки (от 0 до attempts - 1).
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить асинхронное действие action().
            // Если оно завершается успешно, возвращаем результат и выходим из метода.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Если возникла ошибка HttpRequestException и это не последняя попытка,
            // делаем паузу перед следующей попыткой.
            // Задержка растёт экспоненциально: 200 мс * 2^i (backoff strategy).
            // Это помогает избежать перегрузки сервера при частых повторных запросах.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
        // Если возникла другая ошибка (не HttpRequestException) или это последняя попытка,
        // исключение пробрасывается выше (не перехватывается).
    }

    // Этот код теоретически недостижим, так как:
    // - либо действие выполнится успешно и мы вернём результат из try-блока,
    // - либо на последней попытке исключение не будет перехвачено (условие when не выполнится)
    //   и пробросится выше.
    // Однако компилятор требует возврата значения из метода, поэтому выбрасываем исключение.
    throw new InvalidOperationException("unreachable");
}
