// Экспортируем функцию debounce, которая принимает функцию fn и задержку ms.
// Дженерик T ограничивает тип fn так, чтобы он был функцией, принимающей любые аргументы
// и возвращающей void.
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная t хранит идентификатор таймера setTimeout.
  // Изначально она undefined, так как таймер ещё не установлен.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию-обёртку, которая сохраняет сигнатуру оригинальной функции fn.
  // Parameters<T> извлекает типы аргументов оригинальной функции, чтобы обёртка принимала те же аргументы.
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен (t не undefined), отменяем предыдущий вызов setTimeout.
    // Это гарантирует, что fn будет выполнена только после последнего вызова обёртки.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер на выполнение fn через ms миллисекунд.
    // Если до истечения этого времени обёртка будет вызвана снова, предыдущий таймер будет отменён.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

