fun <K, V> MutableMap<K, V>.getOrPutSafe(key: K, factory: () -> V): V =
    // Синхронизируем доступ к объекту карты, чтобы избежать гонок данных
    // при одновременном вызове из разных потоков
    synchronized(this) {
        // Пытаемся получить существующее значение по ключу
        this[key]
            // Если значение отсутствует (null), вызываем фабрику для создания нового
            ?: factory()
            // Если значение было создано фабрикой, сохраняем его в карту
            // и возвращаем это же значение
            .also { this[key] = it }
    }
